import{_ as a,o as n,c as o,j as e,a as i,aa as r}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/diary/en_pocty_podpisu_2.jpg",d="/buildary-help-preview/media/en/diary/en_poznamky1.jpg",l="/buildary-help-preview/media/en/diary/en_poznamky2.jpg",h="/buildary-help-preview/media/en/diary/en_poznamky3.jpg",b=JSON.parse('{"title":"Daily Entries","description":"","frontmatter":{"title":"Daily Entries","wiki":"en:diary:dailyentries"},"headers":[],"relativePath":"en/diary/dailyentries.md","filePath":"en/diary/dailyentries.md","lastUpdated":1794388980000}'),c={name:"en/diary/dailyentries.md"};function y(p,t,u,g,f,m){return n(),o("div",null,[...t[0]||(t[0]=[e("h1",{id:"daily-entries",tabindex:"-1"},[i("Daily Entries "),e("a",{class:"header-anchor",href:"#daily-entries","aria-label":'Permalink to "Daily Entries"'},"​")],-1),e("p",null,"Daily Entries are the most important part of the Project Diary. Entries should be completed on the same day or on the following working day. However, the Buildary application does not force you to do so. It is entirely up to you when you enter the data and when you lock the given day. We believe that doing it later is still better than never doing it.",-1),e("p",null,"Daily Entries are divided into sections according to the type of entry.",-1),e("h4",{id:"video-for-the-introduction",tabindex:"-1"},[i("Video for the Introduction "),e("a",{class:"header-anchor",href:"#video-for-the-introduction","aria-label":'Permalink to "Video for the Introduction"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/NoaEqtiXXms",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),r('<p>The order and content of individual sections can be customized according to the user&#39;s needs and preferences in <a href="/buildary-help-preview/en/diary/diarysetup#diary-settings">Diary Settings</a>.</p><p>The result of the user&#39;s work is the so-called <strong>Daily Report</strong> in PDF format, which contains all data for the given day, including attachments. By signing the Daily Report, the day is locked against any subsequent changes.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Locking is a one-time and irreversible operation.</p></div><p>The basic rule for entering and editing Daily Entries is that each user can edit or delete only entries they have created themselves (until the entry or day is locked).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Therefore, there is no possibility for one user to change data entered by another user, regardless of the configured permissions.</p></div><h2 id="daily-entry-header" tabindex="-1">Daily Entry Header <a class="header-anchor" href="#daily-entry-header" aria-label="Permalink to &quot;Daily Entry Header&quot;">​</a></h2><p>You can access the Daily Entries window by selecting <strong>Daily Entries</strong> in the application&#39;s left panel.</p><p>The header of the Daily Entries window contains a weekly calendar, which always opens on the current day. You can switch between days by selecting a date in this row. If you need to move outside the displayed days, you can switch between individual weeks using the arrows on either side of the row, or use the calendar icon on the left below the date row.</p><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="" width="600" loading="lazy"></figure><p>The days in the date row are underlined in different colors. The colors indicate the status of the given day, which changes over time:</p><p><strong>Red</strong> – the day contains no data</p><p><strong>Blue</strong> – the day already contains some data but is not locked</p><p><strong>Purple</strong> – the day is locked by the user and can still be unlocked</p><p><strong>Yellow</strong> – the day is in the signing process and is temporarily locked</p><p><strong>Green</strong> – the day is permanently locked. The number indicates the number of electronic signatures on the Daily Report for that day.</p><p><strong>Gray</strong> – non-working day, the day contains no data and is locked</p><h3 id="notes-for-the-day" tabindex="-1">Notes for the Day <a class="header-anchor" href="#notes-for-the-day" aria-label="Permalink to &quot;Notes for the Day&quot;">​</a></h3><figure class="shot" style="--w:400px;"><img src="'+d+'" alt="" width="400" loading="lazy"></figure><p>The Daily Entries window has been visually updated in the section containing the bar with the individual days. You can now add a note to each day. The note is not part of the Daily Entries of the diary and is not included in the PDF file.</p><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="" width="600" loading="lazy"></figure><p>There are two types of notes: <strong>Public</strong> and <strong>Private</strong>. Notes can be added by any user with permission to edit the Project Diary. A Public note is visible to all authorized persons of the given diary, while a Private note is visible only to the user who created it.</p><figure class="shot" style="--w:400px;"><img src="'+h+'" alt="" width="400" loading="lazy"></figure><p>The colored icon makes it easy to see that a note exists for a given day, both in the timeline and in the calendar when selecting a day.</p><h2 id="daily-entry-section" tabindex="-1">Daily Entry Section <a class="header-anchor" href="#daily-entry-section" aria-label="Permalink to &quot;Daily Entry Section&quot;">​</a></h2><p>The main part of the window contains the individual sections into which Daily Entries are divided.</p><p>Work in the individual sections is described in separate sections of the help documentation.</p>',26)])])}const v=a(c,[["render",y]]);export{b as __pageData,v as default};
